'use client'
import React,{useEffect,useRef,useState} from 'react'
import {MathRenderer} from '@/components/MathRenderer'
import './physics.css'
type PracticeFilters={province:string[];city:string[];year:string[];practiced:string[];wrong:string[];type:string[]}
const EMPTY_FILTERS:PracticeFilters={province:[],city:[],year:[],practiced:[],wrong:[],type:[]}
function savedFilters(settings:Record<string,string>):PracticeFilters{
 try{const data=JSON.parse(settings.practiceFilters||'{}');return Object.fromEntries(Object.keys(EMPTY_FILTERS).map(k=>[k,Array.isArray(data[k])?data[k].filter((x:unknown)=>typeof x==='string'):[]])) as PracticeFilters}catch{return {...EMPTY_FILTERS}}
}
type FilterOptions={regions:{province:string;city:string}[];years:number[];types:string[]}
type Figure={id:number;figKey:string;url:string|null;imagePath:string;hash:string|null;matchStatus:string;version:string|null}
type Option={label:string;text:string}
type Sub={number:string;stem:string;options?:Option[];subQuestions?:Sub[]}
type Question={unavailable?:boolean;chapters?:{chapter:string}[];practiceCount?:number;wrongCount?:number;qid:string;paperId:string;paperName:string;province:string;year:number;number:string;type:string;stem:string;options:Option[];subQuestions:Sub[];answerChoice:string;answerText:string;answerBlanks:unknown[];analysis:string;answerStatus:string;figures:Record<string,Figure>;revision:string;draft:string}
type Chapter={id:string;name:string;book:string;formula:string;tip:string;count:number}
type Attempt={id:number;qid:string;chapter:string;answer:string;correct:number;mode:string;created:number;due:number}
type Flag={id:number;qid:string;reason:string}
type WrongAttempt=Attempt&{unavailable?:boolean;wrongCount:number;attemptCount:number;correctCount:number;lastWrongAt:number}
type BankStats={total:number;papers:number;official:number;missing:number;eightOfficial:number;eightMissing:number;otherNine:number;unclassified:number}
type Overview={bank:BankStats;stats:{practiced:number;correct:number};chapters:Chapter[];settings:Record<string,string>;attempts:Attempt[];wrong:WrongAttempt[];due:number;flags:Flag[]}
type Similar={sourceQid:string;items:{question:Question;kind:string;reasons:string[];practiced:boolean;imageNotice:string}[];note:string}
type Identity={userId:string;username:string;name:string;role:'student'|'maintenance'}
type Boot={configured:boolean;logged:boolean;admin:boolean;user:Identity|null}
type StudentStats={stats:{practiced:number;correct:number;attempts:number;correctAttempts:number;lastActive:number|null};wrong:WrongAttempt[];due:number;attempts:Attempt[];chapterStats:{chapter:string;attempts:number;correct:number}[]}
type StudentRow={active:number;id:string;username:string;name:string;stats:StudentStats['stats'];wrong:number;due:number;chapterStats:StudentStats['chapterStats']}
type Source={page:number;path:string;sha256:string;url:string}
let apiUser=''
async function api<T>(name:string,data?:Record<string,unknown>):Promise<T>{
 const url='/api/physics/'+name;const headers={'Content-Type':'application/json',...(apiUser?{'x-physics-user':apiUser}:{})};const r=await fetch(url,data?{method:'POST',headers,body:JSON.stringify(data)}:{cache:'no-store',headers});const value=await r.json();if(!r.ok)throw new Error(value.error||'操作失败');if(name==='bootstrap')apiUser=value.user?.userId||'';return value
}
function query(name:string,values:Record<string,string|number|string[]>){return name+'?'+new URLSearchParams(Object.entries(values).map(([k,v])=>[k,Array.isArray(v)?JSON.stringify(v):String(v)]))}
const typeName:Record<string,string>={single_choice:'单选题',multiple_choice:'多选题',fill_blank:'填空题',experiment:'实验题',calculation:'计算题',drawing:'作图题',comprehensive:'综合题',short_answer:'简答题'}
function Rich({text,q,onManage}:{text:string;q:Question;onManage?:()=>void}){
 return <>{(text||'').split(/(\{\{fig:\s*\d+(?:[:：][\s\S]*?)?\s*\}\})/g).map((part,n)=>{const m=part.match(/^\{\{fig:\s*(\d+)/);if(!m)return <MathRenderer key={n}>{part.replace(/\{\{blank:\s*\d+\}\}/g,' ______ ')}</MathRenderer>;const f=q.figures[m[1]];return <figure key={n} className="question-figure">{f?.url?<a href={f.url} target="_blank" rel="noreferrer"><img src={f.url} alt={'图槽 '+m[1]}/></a>:<div className="missing-figure">图槽 {m[1]} 尚无配图，可标记问题或在内容管理中补图。</div>}<figcaption>图槽 {m[1]} · {f?.matchStatus==='human_confirmed'?'人工已确认':f?.matchStatus==='source_fallback'?'原卷整页占位，需圈选':'配图待核对'} {onManage&&<button onClick={onManage}>核对 / 修改</button>}</figcaption></figure>})}</>
}
function QuestionBody({q,onManage}:{q:Question;onManage?:()=>void}){
 function subs(items:Sub[]):React.ReactNode{return items?.map((s,i)=><div className="sub-question" key={i}><strong>（{s.number}）</strong><Rich text={s.stem} q={q} onManage={onManage}/>{s.options?.map((o,j)=><div key={j}>{o.label}．<Rich text={o.text} q={q} onManage={onManage}/></div>)}{s.subQuestions&&subs(s.subQuestions)}</div>)}
 return <div className="question-body"><Rich text={q.stem} q={q} onManage={onManage}/>{q.options?.map((o,i)=><div className="option-text" key={i}><b>{o.label}．</b><Rich text={o.text} q={q} onManage={onManage}/></div>)}{subs(q.subQuestions)}</div>
}
export default function PhysicsApp(){
 const [boot,setBoot]=useState<Boot|null>(null),[overview,setOverview]=useState<Overview|null>(null)
 const [tab,setTab]=useState('home'),[book,setBook]=useState('八上'),[chapter,setChapter]=useState('sound'),[items,setItems]=useState<Question[]>([]),[total,setTotal]=useState(0),[page,setPage]=useState(0),[search,setSearch]=useState('')
 const [q,setQ]=useState<Question|null>(null),[answer,setAnswer]=useState(''),[hint,setHint]=useState(0),[revealed,setRevealed]=useState(false),[result,setResult]=useState<{correct:boolean;mode:string}|null>(null)
 const [busy,setBusy]=useState(false),[message,setMessage]=useState(''),[username,setUsername]=useState('student'),[password,setPassword]=useState(''),[pin,setPin]=useState(''),[flag,setFlag]=useState(''),[editor,setEditor]=useState<Question|null>(null)
 const [filters,setFilters]=useState<PracticeFilters>(EMPTY_FILTERS),[filterOptions,setFilterOptions]=useState<FilterOptions>({regions:[],years:[],types:[]})
 const [minErrors,setMinErrors]=useState('1')
 const [similar,setSimilar]=useState<Similar|null>(null)
 const [filterExpanded,setFilterExpanded]=useState(false),[directPractice,setDirectPractice]=useState(false)
 const returnTab=useRef('home')
 const [manageExpanded,setManageExpanded]=useState(false),[manageChapters,setManageChapters]=useState<string[]>([]),[paperId,setPaperId]=useState(''),[paperMode,setPaperMode]=useState(false)
 const filterPanelRef=useRef<HTMLElement>(null)
 useEffect(()=>{if(filterExpanded)filterPanelRef.current?.scrollIntoView({behavior:'smooth',block:'start'})},[filterExpanded])
 const practiceRef=useRef<HTMLDivElement>(null)
 const similarRef=useRef<HTMLElement>(null)
 useEffect(()=>{if(similar)similarRef.current?.scrollIntoView({behavior:'smooth',block:'start'})},[similar])
 async function recommend(id:string){await saveDraft();setSimilar(await api<Similar>(query('similar',{qid:id,limit:3})))}
 async function practiceSimilar(next:Question){setDirectPractice(true);if(tab!=='practice')returnTab.current=['home','wrong','history'].includes(tab)?tab:'home';setFilterExpanded(false);const label=(next as Question & {chapters?:{chapter:string}[]}).chapters?.map(c=>c.chapter.split('章').pop()?.trim());const ch=overview?.chapters.find(c=>label?.includes(c.name));if(ch){setChapter(ch.id);await api('settings',{chapter:ch.id,book:ch.book})}await open(next.qid,ch?.id||chapter);setItems([next]);setTotal(1);setPage(0);setTab('practice');setSimilar(null);messageRef.current?.scrollIntoView({block:'start'})}
 const draftChain=useRef(Promise.resolve());const messageRef=useRef<HTMLDivElement>(null)
 async function refresh(){const o=await api<Overview>('overview');setOverview(o);return o}
 async function act(fn:()=>Promise<unknown>){setBusy(true);setMessage('');try{await fn()}catch(e){setMessage((e as Error).message)}finally{setBusy(false)}}
 useEffect(()=>{void act(async()=>{const b=await api<Boot>('bootstrap');setBoot(b);if(b.logged){const o=await refresh();setBook(o.settings.book||'八上');setChapter(o.settings.chapter||'sound');setFilters(savedFilters(o.settings));if(b.user?.role==='maintenance'){setTab('manage');await load(chapter,0,true,EMPTY_FILTERS)}}})},[])
 async function login(){await api(boot?.configured?'login':'setup',{username,password,pin});setPassword('');setPin('');const b=await api<Boot>('bootstrap');setBoot(b);setQ(null);setItems([]);setSimilar(null);setMinErrors('1');setFilters(EMPTY_FILTERS);setResult(null);setEditor(null);setAnswer('');const o=await refresh();setBook(o.settings.book||'八上');setChapter(o.settings.chapter||'sound');setFilters(savedFilters(o.settings));setTab(b.user?.role==='maintenance'?'manage':'home');if(b.user?.role==='maintenance')await load(chapter,0,true,EMPTY_FILTERS)}
 async function saveDraft(){if(!q||result||boot?.user?.role!=='student')return;draftChain.current=draftChain.current.catch(()=>{}).then(()=>api('draft',{qid:q.qid,answer}).then(()=>{}));await draftChain.current}
 async function open(id:string,contextChapter=chapter){await saveDraft();const next=await api<Question>(query('question',{qid:id}));setQ(next);setAnswer(next.draft||'');setHint(0);setRevealed(false);setResult(null);setFlag('');setSimilar(null);const current=overview?.chapters.find(c=>c.id===contextChapter);if(current){setChapter(current.id);await api('settings',{chapter:current.id,book:current.book})}}
 async function load(ch=chapter,pg=0,manage=false,chosen?:PracticeFilters){await saveDraft();let f=chosen||filters;if(!manage&&!chosen&&tab!=='practice')f=await api<PracticeFilters>('practice-preferences');const list=await api<{items:Question[];total:number;page:number;filters:FilterOptions}>(query('questions',{chapter:manage?'':ch,page:pg,search:manage?search:'',manage:manage?'1':'0',...f,...(manage?{chapters:manageChapters,paperId}:{})}));if(!manage&&chosen)await api('practice-preferences',f);setItems(list.items);setTotal(list.total);setPage(list.page);setFilterOptions(list.filters);if(!manage){setDirectPractice(false);if(tab!=='practice'){returnTab.current=['home','wrong','history'].includes(tab)?tab:'home';setFilterExpanded(false)}setFilters({...f});setFilterOptions(list.filters);await api('settings',{book,chapter:ch});setChapter(ch);setTab('practice');if(list.items.length)await open(list.items[0].qid,ch);else{setQ(null);setSimilar(null)}}return list}
 async function chooseManageFilter(key:keyof PracticeFilters,value:string){const next={...filters,[key]:filters[key].includes(value)?filters[key].filter(x=>x!==value):[...filters[key],value]};setFilters(next);await load(chapter,0,true,next)}
 async function backFromPractice(){await saveDraft();setSimilar(null);setFilterExpanded(false);setTab(returnTab.current);await refresh();messageRef.current?.scrollIntoView({block:'start'})}
 async function chooseFilter(key:keyof PracticeFilters,value:string){
  const values=value?(filters[key].includes(value)?filters[key].filter(x=>x!==value):[...filters[key],value]):[]
  const next={...filters,[key]:values}
  if(key==='province')next.city=values.length?next.city.filter(city=>filterOptions.regions.some(r=>r.city===city&&values.includes(r.province))):[]
  await load(chapter,0,false,next)
 }
 async function submit(correct?:boolean){if(!q)return;await saveDraft();const r=await api<{correct:boolean;mode:string}>('attempt',{qid:q.qid,answer,chapter, ...(correct===undefined?{}:{correct})});setResult(r);setRevealed(true);setItems(xs=>xs.map(x=>x.qid===q.qid?{...x,practiceCount:(x.practiceCount||0)+1,wrongCount:(x.wrongCount||0)+(r.correct?0:1)}:x));await refresh()}
 const selected=overview?.chapters.find(c=>c.id===chapter)
 const auto=!!q&&['single_choice','multiple_choice'].includes(q.type)&&q.answerStatus==='official'&&/^[A-E]+$/.test(q.answerChoice||'')
 const latest=new Map<string,Attempt>();overview?.attempts.forEach(a=>{if(!latest.has(a.qid))latest.set(a.qid,a)})
 const correct=Array.from(latest.values()).filter(a=>a.correct).length
 if(!boot)return <div className="physics"><main><p>正在打开物理小步…</p>{message&&<p role="alert">{message}</p>}</main></div>
 if(!boot.logged)return <div className="physics"><main className="login-layout"><section><span className="eyebrow">每天学一点，慢慢弄明白</span><h1>物理小步<span>给自己的学习空间</span></h1><p>从一个问题开始，把概念、思路和方法连起来。<br/>手机、平板、电脑，接着上次继续。</p><div className="orbit">F <span>ρ</span> v <small>探索 · 思考 · 练习</small></div></section><form className="panel login-panel" onSubmit={e=>{e.preventDefault();void act(login)}}><h2>{boot.configured?'账号登录':'设置学生与维护账号'}</h2><p>{boot.configured?'学生使用自己的账号；维护账号可查看学生统计并管理内容。':'默认学生账号为 student，维护账号为 administrator，分别设置密码。'}</p>{boot.configured&&<label>账号<input aria-label="登录账号" autoComplete="username" required value={username} onChange={e=>setUsername(e.target.value)}/></label>}<label>登录密码<input aria-label="登录密码" type="password" autoComplete={boot.configured?'current-password':'new-password'} minLength={boot.configured?6:8} required value={password} onChange={e=>setPassword(e.target.value)}/></label>{!boot.configured&&<label>维护账号密码（至少6位）<input aria-label="维护账号密码" type="password" minLength={6} required value={pin} onChange={e=>setPin(e.target.value)}/></label>}<button className="primary" disabled={busy}>{busy?'正在处理…':boot.configured?'进入学习':'设置并开始'}</button>{message&&<p role="alert" className="error">{message}</p>}</form></main></div>
 return <div className="physics"><header className="app-header"><a className="brand" href="/physics"><span>物</span>物理小步</a><nav aria-label="主要导航">{(boot.user?.role==='maintenance'?[['manage','题库浏览'],['issues','待处理问题'],['students','学生管理']]:[['home','学习首页'],['practice','章节练习'],['wrong','错题复习'],['history','学习记录']]).map(([id,label])=><button aria-current={tab===id?'page':undefined} className={tab===id?'current':''} key={id} onClick={()=>void act(async()=>{await saveDraft();setTab(id);if(id==='practice')await load();if(id==='manage'&&boot.admin)await load(chapter,0,true);await refresh()})}>{label}</button>)}</nav><span className="account-label">{boot.user?.name} · {boot.user?.username}</span><button onClick={()=>void act(async()=>{await saveDraft();await api('logout',{});setBoot(await api('bootstrap'));setOverview(null);setQ(null);setSimilar(null);setEditor(null);setItems([]);setAnswer('')})}>退出</button></header><main><div ref={messageRef} aria-live="polite">{message&&<div className="notice error" role="alert">{message}</div>}</div>{busy&&<p className="loading" role="status">正在处理，请稍候…</p>}
 {tab==='issues'&&boot.admin&&<Issues onEdit={async id=>setEditor(await api<Question>(query('question',{qid:id})))} onChange={refresh}/>}
 {tab==='students'&&boot.user?.role==='maintenance'&&<Students chapters={overview?.chapters||[]} onUnlock={()=>setTab('manage')}/>}
 {tab==='home'&&overview&&<><section className="hero"><div><span className="eyebrow">属于你的物理学习路线</span><h1>今天，也弄懂一点物理。</h1><p>先想一想，再试一试。遇到卡住的地方，我们一步一步来。</p><div className="hero-actions"><button className="primary" disabled={busy} onClick={()=>void act(async()=>{const last=overview.settings.lastQid;const group=await load(chapter);if(last&&group.items.some(x=>x.qid===last))await open(last,chapter)})}>继续 · {selected?.name}</button><button onClick={()=>setTab('wrong')}>复习错题 {overview.due>0&&'· '+overview.due+' 题到期'}</button></div></div><div className="hero-symbol" aria-hidden="true">F<span>=</span>ma<small>观察 · 连接 · 理解</small></div></section><section className="section-title"><div><span className="eyebrow">跟着课堂，稳步前进</span><h2>我的章节</h2></div><div className="segmented">{['八上','八下','九全'].map(b=><button className={book===b?'active':''} key={b} onClick={()=>setBook(b)}>{b==='八上'?'八年级上册':b==='八下'?'八年级下册':'九年级全册'}</button>)}</div></section><p className="muted">按人教版常见章节组织，可根据学校实际进度选择；尚未逐题核准教材适配。同一道题可能关联多个章节，下面的题数存在交叉。</p><div className="chapter-grid">{overview.chapters.filter(c=>c.book===book).map((c,i)=><button className="chapter-card" key={c.id} disabled={busy} onClick={()=>void act(()=>load(c.id))}><span className="chapter-number">{String(i+1).padStart(2,'0')}</span><h3>{c.name}</h3><p>{c.tip}</p><footer><span>{c.count} 道可练习题</span><b>开始 →</b></footer></button>)}</div><div className="stats-grid home-statistics" aria-label="学习统计"><article><b>{overview.bank.total.toLocaleString('zh-CN')}</b><span>题库总量</span></article><article><b>{overview.stats.practiced}</b><span>练习过的题目</span></article><article><b>{overview.stats.correct}</b><span>最近一次答对</span></article><article><b>{overview.wrong.length}</b><span>历史错题</span></article><article><b>{overview.due}</b><span>今天可以复习</span></article></div></>}
 {tab==='practice'&&<><button className="practice-back" disabled={busy} onClick={()=>void act(backFromPractice)}>← 返回{({home:'学习首页',wrong:'错题复习',history:'学习记录'} as Record<string,string>)[returnTab.current]||'上一页'}</button><section className="section-title"><div><span className="eyebrow">一道一道，把思路想清楚</span><h1>章节练习 · {selected?.name}</h1></div></section><section ref={filterPanelRef} className="panel practice-filters" aria-label="章节练习筛选"><div className="filter-collapse-header"><h2>筛选练习</h2><span className="muted">偏好自动保存，切换章节仍然沿用</span><button aria-expanded={filterExpanded} aria-controls="practice-filter-options" disabled={busy} onClick={()=>setFilterExpanded(!filterExpanded)}>{filterExpanded?'收起筛选 ↑':'展开筛选 ↓'}</button><button disabled={busy} onClick={()=>void act(()=>load(chapter,0,false,EMPTY_FILTERS))}>清空筛选偏好</button></div>{filterExpanded&&<div id="practice-filter-options"><p className="muted">每项均可多选，点击立即生效；再次点击取消。同组内满足任意一项，不同组同时满足。</p><FilterChips title="地区" values={filters.province} options={Array.from(new Set([...filterOptions.regions.map(r=>r.province),...filters.province])).filter(Boolean).map(p=>({value:p,label:p}))} busy={busy} onToggle={v=>void act(()=>chooseFilter('province',v))}/><FilterChips title="城市" values={filters.city} options={Array.from(new Set([...filterOptions.regions.filter(r=>filters.province.includes(r.province)).map(r=>r.city),...filters.city])).filter(Boolean).map(c=>({value:c,label:c}))} busy={busy} onToggle={v=>void act(()=>chooseFilter('city',v))}/>{!filters.province.length&&<p className="muted filter-city-hint">选择地区后，可多选对应城市。</p>}<FilterChips title="试卷年份" values={filters.year} options={Array.from(new Set([...filterOptions.years.map(String),...filters.year])).sort((a,b)=>Number(b)-Number(a)).map(y=>({value:y,label:y+'年'}))} busy={busy} onToggle={v=>void act(()=>chooseFilter('year',v))}/><FilterChips title="练习状态" values={filters.practiced} options={[{value:'no',label:'未练习过'},{value:'yes',label:'已练习过'}]} busy={busy} onToggle={v=>void act(()=>chooseFilter('practiced',v))}/><FilterChips title="历史错题" values={filters.wrong} options={[{value:'yes',label:'曾经做错'},{value:'no',label:'从未做错'}]} busy={busy} onToggle={v=>void act(()=>chooseFilter('wrong',v))}/><FilterChips title="题型" values={filters.type} options={Array.from(new Set([...filterOptions.types,...filters.type])).map(t=>({value:t,label:typeName[t]||t}))} busy={busy} onToggle={v=>void act(()=>chooseFilter('type',v))}/><div className="actions"><button className="primary" disabled={busy} onClick={()=>practiceRef.current?.scrollIntoView({behavior:'smooth',block:'start'})}>查看 {total} 道筛选结果 ↓</button></div><p className="muted">空选表示不限；练习状态以已提交答案为准，草稿不算练过。历史错题包含后来答对的题。</p></div>}</section>{selected&&<div className="knowledge"><strong>{selected.name} · 知识卡</strong><MathRenderer>{selected.formula}</MathRenderer><p>{selected.tip}</p></div>}<div className="active-filter-summary" role="region" aria-label="当前筛选条件"><strong>{directPractice?'已保存偏好（当前为指定题目练习）':'当前筛选'}</strong>{(Object.keys(filters) as (keyof PracticeFilters)[]).some(k=>filters[k].length)?(Object.keys(filters) as (keyof PracticeFilters)[]).filter(k=>filters[k].length).map(k=><span className="tag" key={k}>{({province:'地区',city:'城市',year:'年份',practiced:'练习状态',wrong:'历史错题',type:'题型'})[k]}：{filters[k].map(v=>k==='type'?typeName[v]||v:k==='practiced'?(v==='yes'?'已练习':'未练习'):k==='wrong'?(v==='yes'?'曾经做错':'从未做错'):v).join('、')}</span>):<span className="muted">本章节全部题目，无额外筛选</span>}<button disabled={busy} onClick={()=>setFilterExpanded(true)}>修改筛选</button></div><div className="practice-grid" ref={practiceRef}><aside className="panel question-list"><h3>本组练习</h3><p className="muted">共 {total} 题 · 第 {page+1} 组</p>{items.map((item,i)=><button className={q?.qid===item.qid?'selected':''} key={item.qid} onClick={()=>void act(()=>open(item.qid))}><b>{page*8+i+1}</b><span>{typeName[item.type]||item.type}<small>{item.province} · {item.year} · 第{item.number}题</small><small>{item.practiceCount?'已练 '+item.practiceCount+' 次':'未练习'}{item.wrongCount?' · 错 '+item.wrongCount+' 次':''}</small></span></button>)}<div className="actions"><button disabled={busy||page===0} onClick={()=>void act(()=>load(chapter,page-1))}>上一组</button><button disabled={busy||(page+1)*8>=total} onClick={()=>void act(()=>load(chapter,page+1))}>下一组</button></div></aside><section className="panel problem">{q?<><div className="problem-meta"><span>{typeName[q.type]||q.type}</span><span>{q.province} · {q.year} · 第 {q.number} 题</span></div><QuestionBody q={q}/><button disabled={busy} onClick={()=>void act(()=>recommend(q.qid))}>练类似题 · 推荐3题</button><section className="answer-area"><h3>你的思路 / 答案</h3>{['single_choice','multiple_choice'].includes(q.type)&&<div className="choice-buttons">{q.options.map(o=><button aria-label={'选择 '+o.label} aria-pressed={answer.includes(o.label)} className={answer.includes(o.label)?'selected':''} key={o.label} disabled={!!result} onClick={()=>setAnswer(q.type==='single_choice'?o.label:answer.includes(o.label)?answer.replace(o.label,''):answer+o.label)}>{o.label}</button>)}</div>}<textarea aria-label="我的答案" placeholder="写下答案、已知条件或你的解题步骤…" value={answer} disabled={!!result} onChange={e=>setAnswer(e.target.value)} onBlur={()=>{void saveDraft().catch(e=>setMessage(e.message))}}/><p className="muted">离开输入框或切换题目时保存草稿；计算、实验与作图题采用对照答案自评。</p><div className="actions"><button className="primary" disabled={busy||!!result||!answer.trim()} onClick={()=>void act(async()=>{if(auto)await submit();else setRevealed(true)})}>{auto?'提交答案':'查看参考并订正'}</button><button disabled={hint>=2} onClick={()=>setHint(hint+1)}>给我一点提示 {hint}/2</button></div>{hint>0&&<div className="hint"><b>提示 {hint}</b><p>{hint===1?'先找出研究对象，圈出已知量和所求量；尝试用自己的话复述问题。':selected?.tip||'把已知条件对应到物理规律，检查适用条件和单位。'}</p><small>这是通用思考提示，不是本题自动推导的结论。</small></div>}{result&&<div className={'result '+(result.correct?'good':'retry')}><b>{result.correct?'这次答对了，继续保持。':'先别急，看看哪一步需要调整。'}</b><p>{result.correct?'已更新学习记录。':'本次错误已累计到错题本，明天可以再试一次。'}{result.mode==='self'?'（自评记录）':'（按参考选项判定）'}</p></div>}{revealed&&<div className="reference"><h3>参考答案与解析</h3><MathRenderer>{[q.answerChoice,q.answerText,...(q.answerBlanks||[]).map(x=>typeof x==='string'?x:JSON.stringify(x))].filter(Boolean).join('；')||'暂无可靠参考答案，请先标记问题。'}</MathRenderer><MathRenderer>{q.analysis||'题库暂缺详细解析。可先对照知识卡订正，或在内容管理补充解析。'}</MathRenderer>{!auto&&!result&&<div className="actions"><button disabled={busy||!answer.trim()} onClick={()=>void act(()=>submit(true))}>我已掌握（自评）</button><button disabled={busy||!answer.trim()} onClick={()=>void act(()=>submit(false))}>仍需练习（自评）</button></div>}</div>}<details className="feedback"><summary>图片或答案有问题？</summary><textarea aria-label="问题说明" placeholder="例如：配图不对应，或图中文字看不清" value={flag} onChange={e=>setFlag(e.target.value)}/><button disabled={busy||!flag.trim()} onClick={()=>void act(async()=>{await api('flag',{qid:q.qid,reason:flag});setFlag('');setMessage('已记录，稍后可在内容管理处理。')})}>标记问题</button></details></section></>:<p>当前筛选条件下没有题目，请调整条件或重置筛选。</p>}</section></div></>}
 {tab==='wrong'&&<><span className="eyebrow">再遇到一次，就多懂一点</span><h1>错题复习</h1><p className="muted">历史错题始终保留，后续答对也不移出；累计每次提交的错误（含主观题“仍需练习”自评），默认按错误次数从多到少排列。同次数时优先展示最近做错的题。</p><div className="actions"><label>至少错误次数<input aria-label="至少错误次数" type="number" min={1} step={1} value={minErrors} onChange={e=>setMinErrors(e.target.value)}/></label><button onClick={()=>setMinErrors('1')}>显示全部历史错题</button><span>显示 {overview?.wrong.filter(a=>a.wrongCount>=Math.max(1,Math.floor(Number(minErrors)||1))).length||0} / {overview?.wrong.length||0} 题</span></div>{overview?.wrong.length?<div className="review-list">{overview.wrong.filter(a=>a.wrongCount>=Math.max(1,Math.floor(Number(minErrors)||1))).map(a=><article className="panel" key={a.qid}><span className="tag">累计错误 {a.wrongCount} 次</span><span className="tag">{a.correct?'最近一次答对 / 自评掌握':'最近一次答错 / 自评需练习'}</span><h3>{a.qid}</h3>{a.unavailable&&<p className="error">题目待修复，暂不可练习</p>}<p>共练习 {a.attemptCount} 次 · 答对 / 自评掌握 {a.correctCount} 次</p><p>最近答案：{a.answer}</p><p className="muted">最近做错：{new Date(a.lastWrongAt*1000).toLocaleString('zh-CN')} · {a.due<=Date.now()/1000?'已到复习时间':'可提前练习'}</p><button className="primary" disabled={busy||a.unavailable} onClick={()=>void act(async()=>{returnTab.current='wrong';setDirectPractice(true);setFilterExpanded(false);setChapter(a.chapter||chapter);await open(a.qid,a.chapter||chapter);setTab('practice')})}>再试一次</button><button disabled={busy||a.unavailable} onClick={()=>void act(()=>recommend(a.qid))}>换题巩固 · 推荐3题</button></article>)}{!overview.wrong.some(a=>a.wrongCount>=Math.max(1,Math.floor(Number(minErrors)||1)))&&<p className="empty panel">没有符合该错误次数的题目，可以降低筛选次数。</p>}</div>:<div className="empty panel"><h2>暂时没有历史错题</h2><p>开始一组练习，看看自己掌握得怎么样。</p><button onClick={()=>void act(()=>load())}>开始练习</button></div>}</>}
 {tab==='history'&&<><LearningCalendar chapters={overview?.chapters||[]}/><span className="eyebrow">看见每一步进步</span><h1>学习记录</h1><p className="muted">统计来自已提交的练习和自评；题量较少时不推断知识掌握程度。</p><div className="chapter-grid">{overview?.chapters.filter(c=>overview.attempts.some(a=>a.chapter===c.id)).map(c=>{const a=overview.attempts.filter(a=>a.chapter===c.id);return <article className="panel" key={c.id}><h3>{c.name}</h3><p>练习 {a.length} 次 · 正确 / 自评掌握 {a.filter(x=>x.correct).length} 次</p><button onClick={()=>void act(()=>load(c.id))}>继续巩固</button></article>})}</div><div className="history-list panel">{overview?.attempts.length?overview.attempts.slice(0,50).map(a=><div key={a.id}><time>{new Date(a.created*1000).toLocaleString('zh-CN')}</time><span>{a.qid}</span><b>{a.correct?'答对 / 已掌握':'需巩固'}{a.mode==='self'?' · 自评':''}</b></div>):<p>提交第一道练习后，这里会保存你的学习足迹。</p>}</div></>}
 {tab==='manage'&&<><span className="eyebrow">把题目修好，让学习顺畅</span><h1>题库浏览</h1>{!boot.admin?<p>请使用管理员账号登录。</p>:<><div className="actions"><button onClick={()=>{setPaperMode(false);setPaperId('')}}>按题目浏览</button><button onClick={()=>setPaperMode(true)}>按试卷浏览</button><input aria-label="搜索题库" placeholder="搜索题干、地区、年份或试卷名" value={search} onChange={e=>setSearch(e.target.value)} onKeyDown={e=>{if(e.key==='Enter')void act(()=>load(chapter,0,true))}}/><button className="primary" disabled={busy} onClick={()=>void act(()=>load(chapter,0,true))}>搜索题库</button></div>{paperMode?<PaperBrowser search={search} onSelect={id=>{setPaperId(id);setPaperMode(false)}}/>:<><section className="panel"><div className="actions"><button aria-expanded={manageExpanded} onClick={()=>setManageExpanded(!manageExpanded)}>{manageExpanded?'收起题库筛选':'展开题库筛选'}</button>{paperId&&<><span>当前试卷：{paperId}</span><button onClick={()=>setPaperId('')}>清除试卷</button></>}<button onClick={()=>void act(()=>load(chapter,0,true))}>应用筛选</button></div>{manageExpanded&&<><FilterChips title="地区" values={filters.province} options={filterOptions.regions.map(x=>x.province).filter((x,i,a)=>a.indexOf(x)===i).map(x=>({value:x,label:x}))} busy={busy} onToggle={v=>void act(()=>chooseManageFilter('province',v))}/><FilterChips title="年份" values={filters.year} options={filterOptions.years.map(y=>({value:String(y),label:String(y)}))} busy={busy} onToggle={v=>void act(()=>chooseManageFilter('year',v))}/><FilterChips title="题型" values={filters.type} options={filterOptions.types.map(t=>({value:t,label:typeName[t]||t}))} busy={busy} onToggle={v=>void act(()=>chooseManageFilter('type',v))}/><FilterChips title="章节" values={manageChapters} options={(overview?.chapters||[]).map(c=>({value:c.id,label:c.book+' · '+c.name}))} busy={busy} onToggle={v=>setManageChapters(xs=>xs.includes(v)?xs.filter(x=>x!==v):[...xs,v])}/><p className="muted">章节和试卷选择后点击“应用筛选”。</p></>}</section><p className="muted">命中 {total} 题 · 当前显示第 {page*8+1}—{Math.min(page*8+8,total)} 题</p><div className="manage-list">{items.map(item=><article className="panel" key={item.qid}><div className="problem-meta"><span>{item.province} · {item.year} · 第{item.number}题</span><span>{item.qid}</span></div>{item.unavailable&&<p className="tag">未处理 · 已暂停学生练习</p>}<QuestionBody q={item} onManage={()=>setEditor(item)}/><button className="primary" onClick={()=>void act(async()=>setEditor(await api<Question>(query('question',{qid:item.qid}))))}>编辑题目 / 原卷裁图</button><TextAction label="标记未处理" placeholder="问题说明（标记后暂停学生练习）" onSubmit={async reason=>{await api('flag',{qid:item.qid,reason});await refresh();setMessage('已标记未处理，学生练习已排除此题。')}}/></article>)}</div><div className="actions"><button disabled={page===0||busy} onClick={()=>void act(()=>load(chapter,page-1,true))}>上一页</button><button disabled={(page+1)*8>=total||busy} onClick={()=>void act(()=>load(chapter,page+1,true))}>下一页</button></div></>}</>}</>}
 {similar&&<section ref={similarRef} className="panel similar-panel" aria-label="相似题推荐"><div className="actions"><h2>推荐练习</h2><button onClick={()=>setSimilar(null)}>收起推荐</button></div><p className="muted">原题：{similar.sourceQid} · {similar.note}</p>{similar.items.length?similar.items.map(item=><article key={item.question.qid}><span className="tag">{item.kind} · {item.practiced?'练习过':'尚未练习'}</span><p>{item.reasons.join('；')}</p><p className="muted">{item.question.province} {item.question.year} · 第{item.question.number}题 · {typeName[item.question.type]||item.question.type}</p><QuestionBody q={item.question}/>{item.imageNotice&&<p className="muted">{item.imageNotice}</p>}<button className="primary" disabled={busy} onClick={()=>void act(()=>practiceSimilar(item.question))}>开始这道练习</button></article>):<p>暂未找到答案可靠、配图可用且不重复的相关题目，不勉强推荐。</p>}</section>}
 </main><footer className="app-footer">物理小步 · 独立学生账号 · 跨设备同步　｜　题目与图片可追溯，学习进度跨设备保存</footer>{editor&&<Editor q={editor} onClose={()=>setEditor(null)} onSaved={async next=>{setEditor(next);setItems(xs=>xs.map(x=>x.qid===next.qid?next:x));if(q?.qid===next.qid)setQ(next);await refresh()}}/>}</div>
}
function FilterChips({title,values,options,busy,onToggle}:{title:string;values:string[];options:{value:string;label:string}[];busy:boolean;onToggle:(value:string)=>void}){
 return <fieldset className="filter-chip-row"><legend>{title}</legend><div className="filter-chip-options"><button type="button" disabled={busy} aria-label={title+'：不限'} aria-pressed={!values.length} className={!values.length?'filter-chip selected':'filter-chip'} onClick={()=>onToggle('')}>不限</button>{options.map(o=><button type="button" disabled={busy} aria-label={title+'：'+o.label} aria-pressed={values.includes(o.value)} className={values.includes(o.value)?'filter-chip selected':'filter-chip'} key={o.value} onClick={()=>onToggle(o.value)}>{values.includes(o.value)&&<span aria-hidden="true">✓ </span>}{o.label}</button>)}</div></fieldset>
}
function Editor({q,onClose,onSaved}:{q:Question;onClose:()=>void;onSaved:(q:Question)=>Promise<void>}){
 const [pages,setPages]=useState<Source[]>([]),[page,setPage]=useState(0),[key,setKey]=useState(Object.keys(q.figures)[0]||'1'),[checks,setChecks]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState(''),[notice,setNotice]=useState(''),[box,setBox]=useState<number[]|null>(null),[zoom,setZoom]=useState(100)
 const [stem,setStem]=useState(q.stem),[choice,setChoice]=useState(q.answerChoice||''),[text,setText]=useState(q.answerText||''),[analysis,setAnalysis]=useState(q.analysis||''),[optionsText,setOptionsText]=useState(JSON.stringify(q.options,null,2)),[subsText,setSubsText]=useState(JSON.stringify(q.subQuestions,null,2))
 const image=useRef<HTMLImageElement>(null),canvas=useRef<HTMLCanvasElement>(null),start=useRef<number[]|null>(null),boxRef=useRef<number[]|null>(null)
 async function run(fn:()=>Promise<unknown>){setBusy(true);setError('');setNotice('');try{await fn()}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
 useEffect(()=>{void run(async()=>setPages((await api<{pages:Source[]}>(query('sources',{qid:q.qid}))).pages))},[q.qid])
 useEffect(()=>{setStem(q.stem);setChoice(q.answerChoice||'');setText(q.answerText||'');setAnalysis(q.analysis||'');setOptionsText(JSON.stringify(q.options,null,2));setSubsText(JSON.stringify(q.subQuestions,null,2));reset()},[q.revision,q.figures[key]?.imagePath,q.figures[key]?.version])
 function reset(){boxRef.current=null;setBox(null);setChecks(false);if(canvas.current){canvas.current.width=0;canvas.current.height=0}}
 function point(e:React.PointerEvent){const r=image.current!.getBoundingClientRect();return [Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))]}
 function move(e:React.PointerEvent){if(!start.current)return;const p=point(e);const b=[Math.min(start.current[0],p[0]),Math.min(start.current[1],p[1]),Math.max(start.current[0],p[0]),Math.max(start.current[1],p[1])];boxRef.current=b;setBox(b)}
 function finish(e:React.PointerEvent){if(!start.current)return;move(e);start.current=null;const b=boxRef.current,im=image.current,c=canvas.current;if(!b||!im||!c)return;const w=im.naturalWidth,h=im.naturalHeight,x=Math.floor(b[0]*w),y=Math.floor(b[1]*h),cw=Math.ceil(b[2]*w)-x,ch=Math.ceil(b[3]*h)-y;if(cw<8||ch<8){reset();return}c.width=cw;c.height=ch;c.getContext('2d')!.drawImage(im,x,y,cw,ch,0,0,cw,ch)}
 const f=q.figures[key]
 function expected(){return {qid:q.qid,figKey:key,expectedPath:f?.imagePath||'',expectedHash:f?.hash||null,expectedVersion:f?.version||null,checks:{match:checks,complete:checks,scope:checks,readable:checks}}}
 async function save(name:string,extra:Record<string,unknown>={}){const next=await api<Question>(name,{...expected(),...extra});await onSaved(next);reset();setNotice(name==='undo'?'已恢复上一版本，历史记录保留。':'已保存到题库，学习页面使用新版本。')}
 return <div className="editor-backdrop"><section className="editor" role="dialog" aria-modal="true" aria-label="题目与配图管理"><header><div><span className="eyebrow">内容管理 · {q.province} {q.year} 第{q.number}题</span><h2>对照原卷，修正这一题</h2></div><button disabled={busy} onClick={onClose}>关闭编辑</button></header>{error&&<p className="notice error" role="alert">{error}</p>}{notice&&<p className="notice" role="status">{notice}</p>}{busy&&<p role="status">正在处理…</p>}<details className="text-editor"><summary>修改题干、答案与解析</summary><label>题干<textarea aria-label="编辑题干" value={stem} onChange={e=>setStem(e.target.value)}/></label><label>选项（JSON，可在 text 中添加图槽引用）<textarea aria-label="编辑选项" value={optionsText} onChange={e=>setOptionsText(e.target.value)}/></label><label>子题（JSON）<textarea aria-label="编辑子题" value={subsText} onChange={e=>setSubsText(e.target.value)}/></label><label>选项答案<input aria-label="编辑选项答案" value={choice} onChange={e=>setChoice(e.target.value)}/></label><label>解答内容<textarea aria-label="编辑解答内容" value={text} onChange={e=>setText(e.target.value)}/></label><label>解析<textarea aria-label="编辑解析" value={analysis} onChange={e=>setAnalysis(e.target.value)}/></label><button disabled={busy} onClick={()=>void run(async()=>{await onSaved(await api<Question>('edit',{qid:q.qid,revision:q.revision,stem,answerChoice:choice,answerText:text,analysis,options:JSON.parse(optionsText),subQuestions:JSON.parse(subsText)}));setNotice('题目内容已保存，旧版本已归档。')})}>保存题目内容</button></details><div className="editor-toolbar"><label>目标图槽<select aria-label="目标图槽" value={key} onChange={e=>{setKey(e.target.value);reset()}}>{Array.from(new Set([...Object.keys(q.figures),...(q.stem.match(/\{\{fig:\s*(\d+)/g)||[]).map(x=>x.match(/\d+/)![0]),key])).sort((a,b)=>Number(a)-Number(b)).map(k=><option value={k} key={k}>图槽 {k}</option>)}</select></label><label>新增图槽<input aria-label="新增图槽编号" type="number" min={1} max={9999} placeholder="数字" onChange={e=>{if(e.target.value){setKey(e.target.value);reset()}}}/></label><label>原卷页面<select aria-label="原卷页面" value={page} disabled={!pages.length} onChange={e=>{setPage(Number(e.target.value));reset()}}>{pages.map((p,i)=><option key={p.path} value={i}>原页 {p.page}</option>)}</select></label><label>显示缩放<input aria-label="原卷缩放" type="range" min={60} max={180} step={10} value={zoom} onChange={e=>setZoom(Number(e.target.value))}/></label></div><p className="muted">拖动框选图片及必要标记。页码尚未逐题核准，可浏览本卷全部来源页。新增图槽后，请在题干或选项中添加 {'{{fig:'+key+'}}'} 引用。</p><div className="editor-columns"><div className="source-scroll">{pages.length?<div className="crop-stage" style={{width:zoom+'%'}} onPointerDown={e=>{if(e.button!==0||!image.current?.naturalWidth)return;e.preventDefault();reset();start.current=point(e);e.currentTarget.setPointerCapture(e.pointerId)}} onPointerMove={move} onPointerUp={finish} onPointerCancel={()=>{start.current=null;reset()}}><img ref={image} src={pages[page]?.url} alt="可圈选的原始试卷" draggable={false}/>{box&&<div className="crop-selection" style={{left:box[0]*100+'%',top:box[1]*100+'%',width:(box[2]-box[0])*100+'%',height:(box[3]-box[1])*100+'%'}}/>}</div>:<div className="empty">暂未找到可用原卷页面。保留当前题目，请先补充来源；不会用其他试卷的图片替代。</div>}</div><aside><h3>当前图槽 {key}</h3>{f?.url?<a href={f.url} target="_blank" rel="noreferrer"><img className="current-crop" src={f.url} alt="当前配图"/></a>:<p>尚无配图</p>}<h3>框选预览</h3><canvas ref={canvas} className="crop-preview"/><label className="check"><input aria-label="确认裁图四项检查" type="checkbox" checked={checks} onChange={e=>setChecks(e.target.checked)}/>已核对：对应正确、内容完整、范围合适、清晰可作答</label><div className="editor-actions"><button className="primary" disabled={busy||!box||!checks} onClick={()=>void run(()=>save('crop',{source:pages[page]?.path,box}))}>保存框选配图</button><button disabled={busy||!f?.url||!checks||f.matchStatus==='source_fallback'} onClick={()=>void run(()=>save('confirm'))}>当前图片正确，确认</button><button disabled={busy||!f?.version} onClick={()=>void run(()=>save('undo',{version:f?.version}))}>恢复上一版配图</button></div><small>原始整页与旧图保留。人工确认结果不会被当前自动候选流程覆盖。</small></aside></div></section></div>
}

function Students({chapters,onUnlock}:{chapters:Chapter[];onUnlock:()=>void}){
 const [rows,setRows]=useState<StudentRow[]>([]),[detail,setDetail]=useState<(StudentStats&{student:{id:string;username:string;name:string}})|null>(null)
 const [name,setName]=useState(''),[username,setUsername]=useState(''),[password,setPassword]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState(''),[notice,setNotice]=useState('')
 async function load(){setRows((await api<{students:StudentRow[]}>('students')).students)}
 async function run(fn:()=>Promise<void>){setBusy(true);setError('');try{await fn()}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
 useEffect(()=>{void run(load)},[])
 return <section className="students-page"><span className="eyebrow">维护账号 · 各学生独立记录</span><h1>学生管理</h1><p className="muted">同一账号在各设备共享学习进度；不同账号的答题、错题、草稿和推荐练习状态彼此隔离。主观题正确数包含学生自评。</p>{error&&<div role="alert" className="notice error">{error}</div>}{notice&&<p role="status">{notice}</p>}<div className="actions"><button disabled={busy} onClick={()=>void run(load)}>刷新统计</button></div><div className="chapter-grid">{rows.map(r=><article className="panel" key={r.id}><h2>{r.name}</h2><p className="muted">账号：{r.username}</p><p>已练 {r.stats.practiced} 题 · 最近答对 {r.stats.correct} 题</p><p>提交 {r.stats.attempts} 次 · 答对 / 自评掌握 {r.stats.correctAttempts} 次</p><p>历史错题 {r.wrong} 题 · 到期复习 {r.due} 题</p><p className="muted">最近提交：{r.stats.lastActive?new Date(r.stats.lastActive*1000).toLocaleString('zh-CN'):'尚未提交'}</p><button disabled={busy} onClick={()=>void run(async()=>{await api('student-update',{studentId:r.id,active:!r.active});await load()})}>{r.active?'停用账号':'启用账号'}</button><TextAction label="修改昵称" placeholder="新的昵称" onSubmit={async name=>{await api('student-update',{studentId:r.id,name});await load()}}/><TextAction label="重置密码" placeholder="新密码（至少8位）" password onSubmit={async password=>{await api('student-update',{studentId:r.id,password});setNotice('密码已重置，旧登录已失效')}}/><button disabled={busy} onClick={()=>void run(async()=>setDetail(await api(query('student-stats',{studentId:r.id}))))}>查看 {r.name} 的明细</button></article>)}</div>{detail&&<section className="panel"><h2>{detail.student.name} · 学习明细</h2><button onClick={()=>setDetail(null)}>收起明细</button><LearningCalendar studentId={detail.student.id} chapters={chapters}/><h3>章节统计</h3>{detail.chapterStats.length?detail.chapterStats.map(c=><p key={c.chapter}>{chapters.find(x=>x.id===c.chapter)?.name||'未标注章节'}：提交 {c.attempts} 次，答对 / 自评掌握 {c.correct} 次</p>):<p>暂无练习记录</p>}<h3>历史错题（按错误次数排序）</h3>{detail.wrong.length?detail.wrong.map(a=><p key={a.qid}>{a.qid}：累计错误 {a.wrongCount} 次 / 共练习 {a.attemptCount} 次 · 最近{a.correct?'答对 / 自评掌握':'答错 / 自评需练习'}</p>):<p>暂无历史错题</p>}<h3>最近提交（最多500次）</h3>{detail.attempts.map(a=><div className="flag-row" key={a.id}><p>{a.qid}<small>{new Date(a.created*1000).toLocaleString('zh-CN')} · {a.mode==='self'?'自评':'选项判定'}</small></p><p>{a.answer} · {a.correct?'答对 / 已掌握':'待巩固'}</p></div>)}</section>}<form className="panel student-form" onSubmit={e=>{e.preventDefault();void run(async()=>{const r=await api<{students:StudentRow[]}>('students',{username,name,password});setRows(r.students);setPassword('');setName('');setUsername('');setNotice('学生账号已创建，可在其他设备使用该账号登录。')})}}><h2>新增学生账号</h2><label>姓名 / 昵称<input aria-label="学生姓名" required maxLength={40} value={name} onChange={e=>setName(e.target.value)}/></label><label>登录账号<input aria-label="新学生账号" required minLength={3} maxLength={32} pattern="[a-z0-9][a-z0-9_-]{2,31}" value={username} onChange={e=>setUsername(e.target.value)}/><small>3—32位小写字母、数字、下划线或连字符</small></label><label>登录密码<input aria-label="新学生密码" type="password" autoComplete="new-password" required minLength={8} value={password} onChange={e=>setPassword(e.target.value)}/></label><button className="primary" disabled={busy}>创建学生账号</button></form></section>
}

function Issues({onEdit,onChange}:{onEdit:(id:string)=>Promise<void>;onChange:()=>Promise<unknown>}){
 const [page,setPage]=useState(0),[total,setTotal]=useState(0),[start,setStart]=useState(''),[end,setEnd]=useState('')
 const [state,setState]=useState('open'),[search,setSearch]=useState(''),[items,setItems]=useState<(Flag&{state:string;created:number})[]>([]),[history,setHistory]=useState<{id:number;qid:string;actor:string;action:string;detail:string;created:number}[]>([]),[error,setError]=useState('')
 async function load(pg=page){try{setItems((await api<{items:typeof items}>(query('issues',{state,search}))).items);const result=await api<{items:typeof history;total:number}>(query('management-history',{search,page:pg,start,end}));setHistory(result.items);setTotal(result.total);setError('')}catch(e){setError((e as Error).message)}}
 useEffect(()=>{void load()},[state,page])
 return <section><h1>待处理问题</h1><p>未处理题目暂停向所有学生提供练习；全部问题处理后恢复。修改内容不会自动标记已处理。</p>{error&&<p role="alert">{error}</p>}<div className="actions"><button onClick={()=>setState('open')} aria-pressed={state==='open'}>未处理</button><button onClick={()=>setState('resolved')} aria-pressed={state==='resolved'}>已处理</button><input aria-label="查询问题与历史" placeholder="题号、试卷、原因或历史内容" value={search} onChange={e=>setSearch(e.target.value)}/><label>历史开始日期<input type="date" value={start} onChange={e=>setStart(e.target.value)}/></label><label>历史结束日期<input type="date" value={end} onChange={e=>setEnd(e.target.value)}/></label><button onClick={()=>{setPage(0);void load(0)}}>查询</button></div>{items.map(f=><article className="panel" key={f.id}><h3>{f.qid}</h3><p>{f.reason}</p><small>{new Date(f.created*1000).toLocaleString('zh-CN')}</small><div className="actions"><button onClick={()=>void onEdit(f.qid)}>打开题目</button><TextAction label={state==='open'?'标记已处理':'重新标记未处理'} placeholder="处理说明 / 重新标记原因" onSubmit={async note=>{await api(state==='open'?'resolve':'reopen',{id:f.id,note});await load();await onChange()}}/></div></article>)}{!items.length&&<p>暂无符合条件的问题。</p>}<h2>处理与修改历史</h2><p className="muted">历史完整保留，按题号、试卷、修改内容和日期查询，每页20条。</p>{history.map(h=><details className="panel" key={h.id}><summary>{new Date(h.created*1000).toLocaleString('zh-CN')} · {h.qid} · {({legacy_image:'历史配图版本',legacy_edit:'历史题目修改',legacy_issue:'历史问题导入',flag:'标记未处理',resolve:'标记已处理',reopen:'重新标记未处理',edit:'修改题目',crop:'人工裁图',confirm:'确认图片',undo:'恢复图片'} as Record<string,string>)[h.action]||h.action}</summary><p>操作人：{h.actor}</p><HistoryDetail detail={h.detail}/></details>)}<div className="actions"><span>历史共{total}条 · 第{page+1}页</span><button disabled={!page} onClick={()=>setPage(page-1)}>上一页历史</button><button disabled={(page+1)*20>=total} onClick={()=>setPage(page+1)}>下一页历史</button></div></section>
}

type CalendarDay={date:string;attempts:number;questions:number;correct:number;chapters:{chapter:string;attempts:number;questions:number;correct:number}[];items:Attempt[]}
function LearningCalendar({studentId,chapters}:{studentId?:string;chapters:Chapter[]}){
 const date=(d:Date)=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(d)
 const [start,setStart]=useState(date(new Date(Date.now()-6*86400000))),[end,setEnd]=useState(date(new Date())),[days,setDays]=useState<CalendarDay[]>([]),[selected,setSelected]=useState(''),[error,setError]=useState('')
 async function load(){try{setDays((await api<{days:CalendarDay[]}>(query('learning-calendar',{start,end,...(studentId?{studentId}:{})}))).days);setError('')}catch(e){setError((e as Error).message)}}
 useEffect(()=>{void load()},[studentId,start,end])
 const colors=['#246b56','#c28a34','#527db1','#975ba4','#b75f63','#718b40'];const names=Array.from(new Set(days.flatMap(d=>d.chapters.map(c=>c.chapter))));const max=Math.max(1,...days.map(d=>d.attempts));const chosen=days.find(d=>d.date===selected)
 return <section className="panel learning-calendar"><h2>每日学习统计</h2><div className="actions"><label>开始日期<input aria-label="统计开始日期" type="date" value={start} onChange={e=>setStart(e.target.value)}/></label><label>结束日期<input aria-label="统计结束日期" type="date" value={end} onChange={e=>setEnd(e.target.value)}/></label>{[7,30].map(n=><button key={n} onClick={()=>{setStart(date(new Date(Date.now()-(n-1)*86400000)));setEnd(date(new Date()))}}>近{n}天</button>)}</div>{error&&<p role="alert">{error}</p>}<p className="muted">按北京时间统计；柱形按章节展示提交次数，绿色横条展示正确率。主观题含自评；同题重复提交计多次，题数按日去重。</p><div className="calendar-chart" aria-label="每日章节练习与正确率">{days.map(d=><button className="calendar-day" key={d.date} onClick={()=>setSelected(d.date)} aria-label={d.date+'，练习'+d.attempts+'次，正确'+d.correct+'次'}><div className="calendar-stack">{d.chapters.map(c=><span key={c.chapter} style={{height:160*c.attempts/max,background:colors[names.indexOf(c.chapter)%colors.length]}} title={(chapters.find(x=>x.id===c.chapter)?.name||'未标注')+' '+c.questions+'题 / '+c.attempts+'次'}/>)}</div><b>{d.attempts}次 / {d.questions}题</b><span>{d.date.slice(5)}</span><span className="accuracy-track"><i style={{width:(d.attempts?100*d.correct/d.attempts:0)+'%'}}/></span><small>{d.attempts?Math.round(100*d.correct/d.attempts)+'%':'—'}</small></button>)}</div><div className="actions">{names.map((id,i)=><span key={id}><i style={{display:'inline-block',width:12,height:12,background:colors[i%colors.length],marginRight:6}}/>{chapters.find(c=>c.id===id)?.name||'未标注'}</span>)}</div>{chosen&&<div><h3>{chosen.date} · {chosen.correct}/{chosen.attempts} 次答对</h3>{chosen.chapters.map(c=><p key={c.chapter}>{chapters.find(x=>x.id===c.chapter)?.name||'未标注'}：{c.questions}题 / {c.attempts}次，答对{c.correct}次</p>)}{chosen.items.map(a=><p key={a.id}>{new Date(a.created*1000).toLocaleTimeString('zh-CN',{timeZone:'Asia/Shanghai'})} · {a.qid} · {a.correct?'答对 / 自评掌握':'需巩固'}</p>)}</div>}</section>
}

function TextAction({label,placeholder,password=false,onSubmit}:{label:string;placeholder:string;password?:boolean;onSubmit:(text:string)=>Promise<unknown>}){
 const [expanded,setExpanded]=useState(false),[text,setText]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState('')
 return <div>{!expanded?<button onClick={()=>setExpanded(true)}>{label}</button>:<form className="actions" onSubmit={async e=>{e.preventDefault();setBusy(true);setError('');try{await onSubmit(text.trim());setText('');setExpanded(false)}catch(e){setError((e as Error).message)}finally{setBusy(false)}}}><label>{placeholder}<input aria-label={placeholder} type={password?'password':'text'} autoComplete={password?'new-password':'off'} required minLength={password?8:1} value={text} onChange={e=>setText(e.target.value)}/></label><button disabled={busy||!text.trim()} type="submit">确认{label}</button><button disabled={busy} type="button" onClick={()=>{setExpanded(false);setText('')}}>取消</button>{error&&<p role="alert">{error}</p>}</form>}</div>
}

function PaperBrowser({search,onSelect}:{search:string;onSelect:(id:string)=>void}){
 const [papers,setPapers]=useState<{paperId:string;stem:string;province:string;year:number;nQuestions:number}[]>([]),[error,setError]=useState('')
 useEffect(()=>{void api<{items:typeof papers}>(query('papers',{search})).then(r=>{setPapers(r.items);setError('')}).catch(e=>setError(e.message))},[search])
 return <section><h2>按试卷浏览 · {papers.length}套</h2>{error&&<p role="alert">{error}</p>}<div className="chapter-grid">{papers.map(p=><article className="panel" key={p.paperId}><h3>{p.stem}</h3><p>{p.province} · {p.year} · {p.nQuestions}题</p><button onClick={()=>onSelect(p.paperId)}>选择本卷</button></article>)}</div><p className="muted">选择试卷后点击“应用筛选”查看题目。</p></section>
}

function HistoryDetail({detail}:{detail:string}){
 const d=JSON.parse(detail),labels:Record<string,string>={stem:'题干',answerChoice:'答案选项',answerText:'参考答案',analysis:'解析',options:'选项',subQuestions:'子题',figures:'配图'}
 const text=(v:unknown)=>typeof v==='string'?v:JSON.stringify(v,null,2)
 return <div>{(d.request?.note||d.request?.reason||d.note)&&<p>说明：{d.request?.note||d.request?.reason||d.note}</p>}{d.importedIssue&&<p>{d.importedIssue.reason} · {d.importedIssue.state==='open'?'未处理':'已处理'}</p>}{Object.entries(labels).filter(([k])=>d.before&&d.after&&JSON.stringify(d.before[k])!==JSON.stringify(d.after[k])).map(([k,label])=><div key={k}><h3>{label}</h3><p>修改前</p><pre style={{whiteSpace:'pre-wrap',overflowWrap:'anywhere'}}>{text(d.before[k])}</pre><p>修改后</p><pre style={{whiteSpace:'pre-wrap',overflowWrap:'anywhere'}}>{text(d.after[k])}</pre></div>)}{d.request?.source&&<p>原卷页：{d.after?.figures?.[d.request.figKey]?.page||'详见配图版本'} · 圈选范围：{d.request.box?.join('，')}</p>}{(d.legacyVersion||(!d.before&&!d.importedIssue))&&<details><summary>查看历史版本内容</summary><pre style={{whiteSpace:'pre-wrap',overflowWrap:'anywhere'}}>{JSON.stringify(d,null,2)}</pre></details>}</div>
}
